mapper.select:
SELECT COUNT(*)
FROM cw_refund
WHERE order_id = #{orderId}
  AND type = #{type}
  AND active_marker = 'ACTIVE'

mapper.update:
UPDATE cw_refund
SET application_status = #{applicationStatus},
    status = #{status},
    active_marker = #{activeMarker}
WHERE refund_no = #{refundNo}
  AND application_status = #{expectedStatus}

UPDATE cw_refund
SET approval_id = #{approvalId}
WHERE refund_no = #{refundNo}

UPDATE cw_refund
SET application_status = #{applicationStatus},
    status = #{status},
    active_marker = #{activeMarker},
    execution_reference = #{executionReference},
    execution_failure_reason = #{executionFailureReason},
    executed_at_ms = #{executedAtMs}
WHERE refund_no = #{refundNo}
  AND application_status = #{expectedStatus}
